"use client";

import { forwardRef, useEffect, useRef, useState, type CSSProperties, type HTMLAttributes, type ReactNode } from "react";
import { textAnimateDefaults, type TextAnimateSpecProps } from "../generated/text-animate.types";
import { cx } from "../utils/cx";
import { motionVars, prefersReducedMotion, useIsomorphicLayoutEffect, useReducedMotion } from "../utils/motion";
import { splitLines, splitWords } from "../utils/split-text";

export interface TextAnimateProps
  extends TextAnimateSpecProps,
    Omit<HTMLAttributes<HTMLSpanElement>, keyof TextAnimateSpecProps | "className" | "children"> {
  className?: string;
}

type Phase = "idle" | "wait" | "run";

/**
 * Text that animates in by character, word or line with a preset. The full text is in the server HTML
 * and is also given to screen readers as visually hidden text; the animated copy is hidden from them.
 * Animation starts after mount; reduced motion and isPaused show the text as it is.
 */
export const TextAnimate = forwardRef<HTMLSpanElement, TextAnimateProps>(function TextAnimate(
  {
    children,
    by = textAnimateDefaults.by,
    animation = textAnimateDefaults.animation,
    delay = textAnimateDefaults.delay,
    duration = textAnimateDefaults.duration,
    stagger = textAnimateDefaults.stagger,
    whenInView = textAnimateDefaults.whenInView,
    isPaused = textAnimateDefaults.isPaused,
    className,
    style,
    ...rest
  },
  forwarded,
) {
  const node = useRef<HTMLSpanElement | null>(null);
  const reduced = useReducedMotion();
  const still = isPaused || reduced;
  const [phase, setPhase] = useState<Phase>("idle");

  useIsomorphicLayoutEffect(() => {
    setPhase(still || prefersReducedMotion() ? "idle" : "wait");
  }, [still, children, by, animation]);

  useEffect(() => {
    if (phase !== "wait") return;
    const el = node.current;
    if (!whenInView || !el || typeof IntersectionObserver === "undefined") {
      setPhase("run");
      return;
    }
    const watcher = new IntersectionObserver(
      ([entry]) => {
        if (!entry.isIntersecting) return;
        watcher.disconnect();
        setPhase("run");
      },
      { rootMargin: "0px 0px -8% 0px" },
    );
    watcher.observe(el);
    return () => watcher.disconnect();
  }, [phase, whenInView]);

  let n = 0;
  const unit = (content: string) => {
    const i = n++;
    return (
      <span key={i} className="rdm-unit" style={{ "--rdm-i": i } as CSSProperties}>
        {content}
      </span>
    );
  };

  let visual: ReactNode;
  if (by === "line") {
    visual = splitLines(children).map((line, i, all) => (
      <span key={i}>
        {unit(line)}
        {i < all.length - 1 ? <br /> : null}
      </span>
    ));
  } else if (by === "word") {
    visual = splitWords(children).map((word, i, all) => (
      <span key={i}>
        {unit(word)}
        {i < all.length - 1 ? " " : null}
      </span>
    ));
  } else {
    visual = splitWords(children).map((word, i, all) => (
      <span key={i}>
        <span className="rdm-word-nowrap">{Array.from(word).map((ch) => unit(ch))}</span>
        {i < all.length - 1 ? " " : null}
      </span>
    ));
  }

  return (
    <span
      {...rest}
      ref={(el) => {
        node.current = el;
        if (typeof forwarded === "function") forwarded(el);
        else if (forwarded) forwarded.current = el;
      }}
      data-rdm-paused={isPaused || undefined}
      data-rdm-anim={phase}
      className={cx("rdm-text-animate", `rdm-ta-${animation}`, className)}
      style={{ ...motionVars({ "--rdm-d": `${duration}s`, "--rdm-s": `${stagger}s`, "--rdm-delay": `${delay}s` }), ...style }}
    >
      <span className="sr-only">{children}</span>
      <span aria-hidden="true">{visual}</span>
    </span>
  );
});

// Generated by rdloom codegen from specs/text-animate.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

export const textAnimateByValues = ["character", "word", "line"] as const;
export const textAnimateAnimationValues = ["fadeIn", "blurIn", "slideUp", "scaleUp"] as const;

/** Text that animates in by character, word or line using a preset: fade in, blur in, slide up or scale up. The words are real text in the page from the start. */
export interface TextAnimateSpecProps {
  /**
   * The text. In line mode, each new line (a newline character) is one unit.
   */
  children: string;
  /**
   * What is animated one after another.
   * @default "word"
   */
  by?: "character" | "word" | "line";
  /**
   * The preset each unit plays.
   * @default "fadeIn"
   */
  animation?: "fadeIn" | "blurIn" | "slideUp" | "scaleUp";
  /**
   * Seconds before the first unit starts.
   * @default 0
   */
  delay?: number;
  /**
   * Seconds each unit takes.
   * @default 0.5
   */
  duration?: number;
  /**
   * Seconds between one unit starting and the next.
   * @default 0.05
   */
  stagger?: number;
  /**
   * Waits until the text scrolls into view before playing.
   * @default false
   */
  whenInView?: boolean;
  /**
   * Stops the animation and shows the finished text. Moving content that lasts more than five seconds should be stoppable.
   * @default false
   */
  isPaused?: boolean;
}

export const textAnimateDefaults = {
  by: "word",
  animation: "fadeIn",
  delay: 0,
  duration: 0.5,
  stagger: 0.05,
  whenInView: false,
  isPaused: false,
} as const;

export const textAnimateMeta = {
  "name": "TextAnimate",
  "version": "0.1.0",
  "status": "experimental",
  "role": "text"
} as const;
